        text = re.sub('\sdue\:[0-9]{4}\-[0-9]{2}\-[0-9]{2}', ' due:' + str(newDate)[0:10], text)
        return text

    @property
    def thresholdString(self):
        return dateString(self.threshold)

    #New: Helper method to calculate next due date for recurring tasks
    def _calculateNextDueDate(self):
        if not self.recursion or not self.due:
            return None

        increment = int(self.recursion.increment)
        interval = self.recursion.interval

        if self.recursion.mode == recursiveMode.originalDueDate:
            base_date = self.due
        else:  # completitionDate mode
            base_date = datetime.combine(self.completion_date, time.min)

        if interval == 'b':
            delta = timedelta(days=increment)
        elif interval == 'd':
            delta = timedelta(days=increment)
        elif interval == 'w':
            delta = timedelta(weeks=increment)
        elif interval == 'm':
            delta = timedelta(days=increment * 30)
        elif interval == 'y':
            delta = timedelta(days=increment * 365)
        else:
            return None

        return base_date + delta

    #Modify: Updated setCompleted method to handle recurring tasks
    def setCompleted(self):
        if self.is_complete:
            return
        self.completion_date = date.today()
        date_string = self.completion_date.strftime('%Y-%m-%d')
        self._text = 'x %s %s' % (date_string, self._text)
        self.is_complete = True

        #New: Calculate and update due date for recurring tasks
        if self.recursion and self.due:
            next_due = self._calculateNextDueDate()
            if next_due:
                self.due = next_due
                self._text = self.updateDateInTask(self._text, next_due)

        self.modified.emit(self)

    def setPending(self):
        if not self.is_complete:
            return
        words = self._text.split(" ")
        d = self._parseDate(words[1])
        if d:
            self._text = " ".join(words[2:])
        else:
            self._text = " ".join(words[1:])
        self.is_complete = False
        self.completion_date = None
        self.modified.emit(self)

    def toHtml(self):
        htmlizer = TaskHtmlizer()
        return htmlizer.task2html(self)

    def increasePriority(self):
        if self.is_complete:
            return
        if not self.priority:
            self.priority = self._lowest_priority
            self._text = "({}) {}".format(self.priority, self._text)
        elif self.priority != self._highest_priority:
            self.priority = chr(ord(self.priority) - 1)
            self._text = "({}) {}".format(self.priority, self._text[4:])
        self.modified.emit(self)

    def decreasePriority(self):
        if self.is_complete:
            return
        if self.priority >= self._lowest_priority:
            self.priority = ""
            self._text = self._text[4:]
            self._text = self._text.replace("({})".format(self.priority), "", 1)
        elif self.priority:
