from pygments.token import Token
from radian.lexer import CustomSLexer

lexer = CustomSLexer()


def cursor_in_string(document):
    # #Modify: Enhanced to handle multi-line strings
    # Get all text up to cursor, not just current line
    full_text = document.text_before_cursor
    tokens = list(lexer.get_tokens(full_text))
    if not tokens:
        return False

    # #New: Track string state across multiple lines
    string_stack = []
    for t, s in tokens:
        if t is Token.Literal.String:
            # Track opening and closing of strings
            if s.startswith(('"', "'", '"""', "'''")):
                string_stack.append(t)
            elif string_stack and string_stack[-1] is Token.Literal.String:
                string_stack.pop()
        elif t is Token.Error:
            return True

    # #Modify: Return True if we're inside a string context
    if string_stack:
        return True

    # #New: Check last meaningful token for string context
    for t, s in reversed(tokens):
        if t is Token.Text and s == "\n":
            continue
        elif t is Token.Error:
            return True
        elif t is Token.Literal.String:
            return True
        else:
            return False
    return False


# #New: Additional helper function for multi-line string detection
def is_in_multiline_string(document):
    """Check if cursor is within a multi-line string (triple quotes)."""
    text = document.text_before_cursor
    triple_double = text.count('"""')
    triple_single = text.count("'''")
    return (triple_double % 2 == 1) or (triple_single % 2 == 1)


