class AttentionMechanism(nn.Module):
    def __init__(self, hidden_dim):
        super(AttentionMechanism, self).__init__()
        self.hidden_dim = hidden_dim
        self.attention_weights = nn.Linear(hidden_dim, 1)

    def forward(self, encoder_outputs):
        # encoder_outputs shape: (batch_size, seq_len, hidden_dim)
        attn_weights = self.attention_weights(encoder_outputs)
        attn_weights = torch.softmax(attn_weights, dim=1)
        context_vector = torch.bmm(attn_weights.transpose(1, 2), encoder_outputs)
        return context_vector.squeeze(1)

