class Once(object):
    def __init__(self):
        self.m = Mutex()
        self.done = AtomicLong(0)

    def do(self, func):
        @functools.wraps(func)
        def _wrapper(*args, **kwargs):
            if self.done == 1:
                return

            with self.m:
                if self.done == 0:
                    func(*args, **kwargs)
                    self.done.value = 1

        return _wrapper

