from .once import Once

class LoggingOnce(Once):
    def __init__(self):
        super(LoggingOnce, self).__init__()
        self.log = []

    def do(self, func):
        @functools.wraps(func)
        def _wrapper(*args, **kwargs):
            if self.done == 1:
                return

            with self.m:
                if self.done == 0:
                    func(*args, **kwargs)
                    self.done.value = 1
                    self.log.append((func.__name__, args, kwargs))

        return _wrapper

