# New: Cache decorator for memoizing function results
def cache_result(func):
    """Decorator to cache function results based on query parameters"""
    cached_data = {}

    @wraps(func)
    def wrapper(query_parameters):
        # Convert dict to tuple for hashability
        cache_key = str(query_parameters)
        if cache_key not in cached_data:
            cached_data[cache_key] = func(query_parameters)
        return cached_data[cache_key]

    return wrapper

