class ExpensiveClassMeta(type):
    """Metaclass to implement singleton pattern for ExpensiveClass"""
    _instances = {}

    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super(ExpensiveClassMeta, cls).__call__(*args, **kwargs)
        return cls._instances[cls]

class ExpensiveClass(object, metaclass=ExpensiveClassMeta):
    """A fake Class that takes a long time to fully initialize (now cached via singleton)"""

