    grad_np = grad.cpu().float().numpy()
    image = np.zeros((grad.shape[2], grad.shape[3]))
    for i in range(grad_np.shape[1]):
           image = np.maximum(image, grad_np[0,i,:,:])
    return stretch_image(image).astype(imtype)

