api_key = os.environ.get("ANTHROPIC_API_KEY")


def get_client():
    if not api_key:
        raise ValueError("ANTHROPIC_API_KEY environment variable not set")

    return anthropic.Anthropic(api_key=api_key)


class AnthropicCompletionProvider(CompletionProvider):
    def complete(
        self, messages: List[Message], args: dict, stream: bool = False
    ) -> Iterator[CompletionEvent]:
        # #Modify: Initialize stop_sequences with default and custom values
        stop_sequences = [anthropic.HUMAN_PROMPT]
        if "stop_sequences" in args and args["stop_sequences"]:
            if isinstance(args["stop_sequences"], list):
                stop_sequences.extend(args["stop_sequences"])
            else:
                stop_sequences.append(args["stop_sequences"])

        kwargs = {
            "stop_sequences": stop_sequences,
            "max_tokens": 4096,
            "model": args["model"],
        }

        if "temperature" in args:
            kwargs["temperature"] = args["temperature"]
        if "top_p" in args:
            kwargs["top_p"] = args["top_p"]

        if len(messages) > 0 and messages[0]["role"] == "system":
            kwargs["system"] = messages[0]["content"]
            messages = messages[1:]

        kwargs["messages"] = messages

        client = get_client()
        input_tokens = None
        try:
            if stream:
                with client.messages.stream(**kwargs) as completion:
                    for event in completion:
                        if event.type == "content_block_delta":
                            yield MessageDeltaEvent(event.delta.text)
                        if event.type == "message_start":
                            input_tokens = event.message.usage.input_tokens
                        if (
                            event.type == "message_delta"
                            and (pricing := claude_pricing(args["model"]))
                            and input_tokens
                        ):
                            yield UsageEvent.with_pricing(
                                prompt_tokens=input_tokens,
                                completion_tokens=event.usage.output_tokens,
                                total_tokens=input_tokens + event.usage.output_tokens,
                                pricing=pricing,
                            )

            else:
                response = client.messages.create(**kwargs, stream=False)
                yield MessageDeltaEvent("".join(c.text for c in response.content))
                if pricing := claude_pricing(args["model"]):
                    yield UsageEvent.with_pricing(
                        prompt_tokens=response.usage.input_tokens,
                        completion_tokens=response.usage.output_tokens,
                        total_tokens=response.usage.input_tokens
                        + response.usage.output_tokens,
                        pricing=pricing,
                    )
        except anthropic.BadRequestError as e:
            raise BadRequestError(e.message) from e
        except anthropic.APIError as e:
            raise CompletionError(e.message) from e


