"""A MongoDB-based caching core for cachier."""

import pickle
import sys
import time
import warnings
import logging  # #New for logging wait times
from contextlib import suppress
from datetime import datetime

from .._types import HashFunc, Mongetter

with suppress(ImportError):
    from bson.binary import Binary
    from pymongo import ASCENDING, IndexModel
    from pymongo.errors import OperationFailure

from .base import RecalculationNeeded, _BaseCore, _get_func_str

MONGO_SLEEP_DURATION_IN_SEC = 1
logger = logging.getLogger(__name__)  # #New for logging

class MissingMongetter(ValueError):
    """Thrown when the mongetter keyword argument is missing."""

class _MongoCore(_BaseCore):
    _INDEX_NAME = "func_1_key_1"

    def __init__(
        self,
        hash_func: HashFunc,
        mongetter: Mongetter,
        wait_for_calc_timeout: int,
    ):
        if "pymongo" not in sys.modules:
            warnings.warn(
                "`pymongo` was not found. MongoDB cores will not function.",
                ImportWarning,
                stacklevel=2,
            )

        super().__init__(hash_func, wait_for_calc_timeout)
        if mongetter is None:
            raise MissingMongetter(
                "must specify ``mongetter`` when using the mongo core"
            )
        self.mongetter = mongetter
        self.mongo_collection = self.mongetter()
        index_inf = self.mongo_collection.index_information()
        if _MongoCore._INDEX_NAME not in index_inf:
            func1key1 = IndexModel(
                keys=[("func", ASCENDING), ("key", ASCENDING)],
                name=_MongoCore._INDEX_NAME,
            )
            self.mongo_collection.create_indexes([func1key1])

    @property
    def _func_str(self) -> str:
        return _get_func_str(self.func)

    def get_entry_by_key(self, key):
        res = self.mongo_collection.find_one(
            {"func": self._func_str, "key": key}
        )
        if not res:
            return key, None
        try:
            entry = {
                "value": pickle.loads(res["value"]),
                "time": res.get("time", None),
                "stale": res.get("stale", False),
                "being_calculated": res.get("being_calculated", False),
            }
        except KeyError:
            entry = {
                "value": None,
                "time": res.get("time", None),
                "stale": res.get("stale", False),
                "being_calculated": res.get("being_calculated", False),
            }
        return key, entry

    def set_entry(self, key, func_res):
        thebytes = pickle.dumps(func_res)
        self.mongo_collection.update_one(
            filter={"func": self._func_str, "key": key},
            update={
                "$set": {
                    "func": self._func_str,
                    "key": key,
                    "value": Binary(thebytes),
                    "time": datetime.now(),
                    "stale": False,
                    "being_calculated": False,
                }
            },
            upsert=True,
        )

    def mark_entry_being_calculated(self, key):
        self.mongo_collection.update_one(
            filter={"func": self._func_str, "key": key},
            update={"$set": {"being_calculated": True}},
            upsert=True,
        )

    def mark_entry_not_calculated(self, key):
        with suppress(OperationFailure):
            self.mongo_collection.update_one(
                filter={
                    "func": self._func_str,
                    "key": key,
                },
                update={"$set": {"being_calculated": False}},
                upsert=False,
            )

    def wait_on_entry_calc(self, key):  # #Modify method signature and implementation
        """Wait for entry calculation and log the time spent waiting."""
        time_spent = 0
        wait_start_time = time.time()  # #New track start time
        while True:
            time.sleep(MONGO_SLEEP_DURATION_IN_SEC)
            time_spent += MONGO_SLEEP_DURATION_IN_SEC
            key, entry = self.get_entry_by_key(key)
            if entry is None:
                elapsed = time.time() - wait_start_time  # #New calculate elapsed time
                logger.warning(f"Entry calculation failed after {elapsed:.2f}s wait for key: {key}")  # #New log warning
                raise RecalculationNeeded()
            if not entry["being_calculated"]:
                elapsed = time.time() - wait_start_time  # #New calculate elapsed time
                logger.info(f"Entry calculation completed after {elapsed:.2f}s wait for key: {key}")  # #New log info
                return entry["value"]
            self.check_calc_timeout(time_spent)

    def clear_cache(self):
        self.mongo_collection.delete_many(filter={"func": self._func_str})

    def clear_being_calculated(self):
        self.mongo_collection.update_many(
            filter={
                "func": self._func_str,
                "being_calculated": True,
            },
            update={"$set": {"being_calculated": False}},
        )

