def calculate_average_visits_per_hour(non_private_counts, private_counts) -> dict:
    """Calculate the average number of visits per hour based on non-private and private counts.

    Returns a dictionary mapping hours to average visits.
    """
    average_visits = {}
    for hour in non_private_counts:
        average_visits[hour] = (non_private_counts[hour] + private_counts[hour]) / 2
    return average_visits

