class JavascriptInjectorMiddleware:
    def __init__(self, app, ws_url):
        self.app = app
        self.ws_url = ws_url

    async def __call__(self, scope, receive, send):
        if scope["type"] == "http":
            async def wrapped_send(event):
                if event["type"] == "http.response.start":
                    event["headers"] = [*event["headers"], (b"Content-Security-Policy", b"default-src 'self'; script-src 'self' 'unsafe-inline';")]
                elif event["type"] == "http.response.body":
                    if event["body"] and b"</body>" in event["body"]:
                        event["body"] = event["body"].replace(b"</body>", f"<script>console.log('Connected to {self.ws_url}');</script></body>".encode())
                await send(event)
            await self.app(scope, receive, wrapped_send)

